// Node 22.18+ can strip the type-only TypeScript used by the reference fixture.
import { readFile, writeFile } from 'node:fs/promises';
import { singleLine, multiWire } from '../feeder.ts';

const connectivity = JSON.parse(await readFile(new URL('../feeder.connectivity.json', import.meta.url), 'utf8'));
const data = { connectivity, singleLine, multiWire };
await writeFile(new URL('gallery-data.js', import.meta.url),
  '// Generated by build-gallery.mjs from the design fixture. Do not hand edit.\nwindow.GALLERY_DATA = ' + JSON.stringify(data) + ';\n');
console.log('Generated gallery-data.js from the connectivity fixture and both projections.');
